class sitemap extends Core { public static $actions = [ 'index' => self::ROLE_VISITOR ]; public static $siteMap = ''; public function index() { $lSep = Helper::checkRewrite() ? '?' : '&'; $lParam = file_exists(self::DATA_DIR . self::$siteContent . '/.default') ? '' : $lSep . 'l=' . self::$siteContent; $lParamHome = file_exists(self::DATA_DIR . self::$siteContent . '/.default') ? '' : '?l=' . self::$siteContent; $items = '<ul>'; foreach ($this->getHierarchy(null, true, null) as $parentId => $childIds) { $items .= ' <li>'; if ($this->getData(['page', $parentId, 'disable']) === false && $this->getUser('role') >= $this->getData(['page', $parentId, 'role'])) { $pageUrl = ($parentId !== $this->getData(['locale', 'homePageId'])) ? Helper::baseUrl() . $parentId . $lParam : Helper::baseUrl(false) . $lParamHome; $items .= '<a href="' . $pageUrl . '">' . $this->getData(['page', $parentId, 'title']) . '</a>'; } else { $items .= $this->getData(['page', $parentId, 'title']); } $isParentBlog = ($this->getData(['page', $parentId, 'moduleId']) === 'blog'); $parentPageModules = $this->getData(['page', $parentId, 'pageModules']); if (is_array($parentPageModules)) { foreach ($parentPageModules as $pm) { if (($pm['moduleId'] ?? '') === 'blog') { $isParentBlog = true; break; } } } if ( $isParentBlog && !empty($this->getData(['module', $parentId, 'posts'])) ) { $items .= '<ul>'; $articleIdsPublishedOns = Helper::arrayColumn($this->getData(['module', $parentId, 'posts']), 'publishedOn', 'SORT_DESC'); $articleIdsStates = Helper::arrayColumn($this->getData(['module', $parentId, 'posts']), 'state', 'SORT_DESC'); $articleIds = []; foreach ($articleIdsPublishedOns as $articleId => $articlePublishedOn) { if ($articlePublishedOn !== null and $articlePublishedOn <= time() and ($articleIdsStates[$articleId] ?? false)) { $articleIds[] = $articleId; } } foreach ($articleIds as $articleId => $article) { if ($this->getData(['module', $parentId, 'posts', $article, 'state']) === true) { $items .= ' <li>'; $items .= '<a href="' . Helper::baseUrl() . $parentId . '/' . $article . $lParam . '">' . $this->getData(['module', $parentId, 'posts', $article, 'title']) . '</a>'; $items .= '</li>'; } } $items .= '</ul>'; } foreach ($childIds as $childId) { $items .= '<ul>'; $items .= ' <li>'; if ($this->getData(['page', $childId, 'disable']) === false && $this->getUser('role') >= $this->getData(['page', $parentId, 'role'])) { $pageUrl = ($childId !== $this->getData(['locale', 'homePageId'])) ? Helper::baseUrl() . $childId . $lParam : Helper::baseUrl(false) . $lParamHome; $items .= '<a href="' . $pageUrl . '">' . $this->getData(['page', $childId, 'title']) . '</a>'; } else { $items .= $this->getData(['page', $childId, 'title']); } $items .= '</li>'; $isChildBlog = ($this->getData(['page', $childId, 'moduleId']) === 'blog'); $childPageModules = $this->getData(['page', $childId, 'pageModules']); if (is_array($childPageModules)) { foreach ($childPageModules as $pm) { if (($pm['moduleId'] ?? '') === 'blog') { $isChildBlog = true; break; } } } if ( $isChildBlog && !empty($this->getData(['module', $childId, 'posts'])) ) { $items .= '<ul>'; $articleIdsPublishedOns = Helper::arrayColumn($this->getData(['module', $childId, 'posts']), 'publishedOn', 'SORT_DESC'); $articleIdsStates = Helper::arrayColumn($this->getData(['module', $childId, 'posts']), 'state', 'SORT_DESC'); $articleIds = []; foreach ($articleIdsPublishedOns as $articleId => $articlePublishedOn) { if ($articlePublishedOn !== null and $articlePublishedOn <= time() and ($articleIdsStates[$articleId] ?? false)) { $articleIds[] = $articleId; } } foreach ($articleIds as $articleId => $article) { if ($this->getData(['module', $childId, 'posts', $article, 'state']) === true) { $items .= ' <li>'; $items .= '<a href="' . Helper::baseUrl() . $childId . '/' . $article . $lParam . '">' . $this->getData(['module', $childId, 'posts', $article, 'title']) . '</a>'; $items .= '</li>'; } } $items .= '</ul>'; } $items .= '</ul>'; } $items .= '</li>'; } $items .= '</ul>'; self::$siteMap = $items; $this->addOutput([ 'title' => Helper::translate('Plan du site'), 'view' => 'index' ]); } }
